-- profiler_questions_batch_3.sql
-- Adds 90 Profiler questions (30 light, 30 medium, 30 deep), taking the pool
-- from 300 to 390, still balanced across the three intensities, because each
-- game cycles light -> medium -> deep. Written after a full family game
-- night where the family noticed repeats (Randy, Nov 23 2026).
--
-- Also adds "Black with an ice cube" to the coffee question (Randy's own
-- order).
--
-- SAFE TO RE-RUN: every insert skips a question whose exact text is already
-- in the table, and the coffee change only fills an empty option slot.
-- New questions show up after the next server restart (the game caches the
-- list), which every deploy does.
--
-- THE CONTENT RULE: every option is one a person would comfortably own out
-- loud, in front of family, on the TV. No politics, religion as identity,
-- sex/dating, bodies, money, health, or questions about people in the room.

-- ---------- The coffee question: Randy's order ----------
UPDATE profiler_questions SET option_g = 'Black with an ice cube'
 WHERE question_text = 'How do you take your coffee?' AND option_g IS NULL;



-- ---------- LIGHT (intensity 1) ----------

-- ---------- SAYS SOMETHING ABOUT YOU (intensity 2) ----------

-- ---------- DEEPER (intensity 3) ----------
-- Check: how many questions at each intensity (expect 130 / 130 / 130), and
-- the coffee question's last option.
SELECT intensity, COUNT(*) AS questions FROM profiler_questions WHERE active GROUP BY intensity ORDER BY intensity;
SELECT option_g AS coffee_last_option FROM profiler_questions WHERE question_text = 'How do you take your coffee?';
